use std::sync::{Arc, Mutex};

use axum::routing::get;
use axum::Router;

pub mod handlers;
pub mod repository;

#[derive(Clone)]
pub struct AppState {
    pub items: Arc<Mutex<repository::ItemRepository>>,
}

pub fn build_router() -> Router {
    let state = AppState {
        items: Arc::new(Mutex::new(repository::ItemRepository::new())),
    };
    Router::new()
        .route("/items", get(handlers::list_items).post(handlers::create_item))
        .with_state(state)
}

