use axum::extract::State;
use axum::http::StatusCode;
use axum::Json;
use serde::Deserialize;

use crate::repository::{Item, ItemRepository};
use crate::AppState;

#[derive(Deserialize)]
pub struct CreateItem {
    pub name: String,
}

pub async fn create_item(
    State(_state): State<AppState>,
    Json(body): Json<CreateItem>,
) -> (StatusCode, Json<Item>) {
    // BUG: ignores the shared state and writes into a brand-new repository
    // that is dropped when this request ends - nothing ever persists, and
    // every item gets id 1.
    let mut repo = ItemRepository::new();
    let item = repo.add(body.name);
    (StatusCode::CREATED, Json(item))
}

pub async fn list_items(State(_state): State<AppState>) -> Json<Vec<Item>> {
    // BUG: reads from another fresh repository - always empty.
    let repo = ItemRepository::new();
    Json(repo.list())
}

