use serde::Serialize;

#[derive(Clone, Serialize)]
pub struct Item {
    pub id: i64,
    pub name: String,
}

pub struct ItemRepository {
    items: Vec<Item>,
    next_id: i64,
}

impl ItemRepository {
    pub fn new() -> Self {
        ItemRepository { items: Vec::new(), next_id: 1 }
    }

    pub fn add(&mut self, name: String) -> Item {
        let item = Item { id: self.next_id, name };
        self.next_id += 1;
        self.items.push(item.clone());
        item
    }

    pub fn list(&self) -> Vec<Item> {
        self.items.clone()
    }
}

