use axum::body::{to_bytes, Body};
use axum::http::{Request, StatusCode};
use serde_json::Value;
use tower::ServiceExt;

async fn send(app: axum::Router, method: &str, uri: &str, body: Option<&str>) -> (StatusCode, Value) {
    let mut builder = Request::builder().method(method).uri(uri);
    let request = match body {
        Some(b) => builder
            .header("content-type", "application/json")
            .body(Body::from(b.to_string()))
            .unwrap(),
        None => builder.body(Body::empty()).unwrap(),
    };
    let res = app.oneshot(request).await.unwrap();
    let status = res.status();
    let bytes = to_bytes(res.into_body(), usize::MAX).await.unwrap();
    let value = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, value)
}

#[tokio::test]
async fn state_is_shared_across_requests() {
    let app = webapp::build_router();

    let (status, first) = send(app.clone(), "POST", "/items",
        Some(r#"{"name": "hammer"}"#)).await;
    assert_eq!(status, StatusCode::CREATED);
    assert_eq!(first["id"], 1);

    let (_, second) = send(app.clone(), "POST", "/items",
        Some(r#"{"name": "nail"}"#)).await;
    assert_eq!(second["id"], 2,
        "second POST got id {} - each request is using a fresh repository", second["id"]);

    let (status, list) = send(app, "GET", "/items", None).await;
    assert_eq!(status, StatusCode::OK);
    let names: Vec<&str> = list.as_array().unwrap().iter()
        .map(|i| i["name"].as_str().unwrap()).collect();
    assert_eq!(names, vec!["hammer", "nail"],
        "items must persist in shared state across requests");
}

